SourceCode.Declaration:
/// <summary>
/// A vendor the worker may order from, with the defaults a new purchase order takes.
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderVendor
{
    str accountNum;
    str name;
    str currencyCode;
    str paymentTerms;
    str deliveryTerms;
    str deliveryMode;
}

Method.Source:
[DataMemberAttribute('AccountNum')]
public str parmAccountNum(str _value = accountNum)
{
    accountNum = _value;
    return accountNum;
}

[DataMemberAttribute('Name')]
public str parmName(str _value = name)
{
    name = _value;
    return name;
}

[DataMemberAttribute('CurrencyCode')]
public str parmCurrencyCode(str _value = currencyCode)
{
    currencyCode = _value;
    return currencyCode;
}

[DataMemberAttribute('PaymentTerms')]
public str parmPaymentTerms(str _value = paymentTerms)
{
    paymentTerms = _value;
    return paymentTerms;
}

[DataMemberAttribute('DeliveryTerms')]
public str parmDeliveryTerms(str _value = deliveryTerms)
{
    deliveryTerms = _value;
    return deliveryTerms;
}

[DataMemberAttribute('DeliveryMode')]
public str parmDeliveryMode(str _value = deliveryMode)
{
    deliveryMode = _value;
    return deliveryMode;
}
